import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import { uv, vec2, vec3, vec4, texture, mix, smoothstep, color, mul, dot, fract } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh } = ctx.THREE;

  const group = new Group();

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;

  const height = 1.5;
  const width = height * aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();
  material.side = ctx.THREE.FrontSide;

  const gradient = mix(
    color(colors.ink),
    color(colors.surface),
    smoothstep(0.0, 1.0, uv().y)
  );

  material.colorNode = vec4(gradient, 1.0);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      tex.wrapS = ctx.THREE.ClampToEdgeWrapping;
      tex.wrapT = ctx.THREE.ClampToEdgeWrapping;

      const texNode = texture(tex, uv());
      const base = mix(texNode.rgb, gradient, 0.28);

      const accentMask = smoothstep(0.94, 0.96, uv().y);
      const withAccent = mix(base, color(colors.accent), mul(accentMask, 0.85));

      const grainUV = mul(uv(), vec2(600.0, 400.0));
      const grain = fract(mul(dot(grainUV, vec2(12.9898, 78.233)), 43758.5453));
      const grainMix = mul(grain, 0.04);
      const finalColor = mix(withAccent, color(colors.paper), grainMix);

      material.colorNode = vec4(finalColor, 1.0);
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return group;
}
